import { json } from "@sveltejs/kit";
import { c as checkPersistentRateLimit } from "../../../../../../../chunks/persistentRateLimit.js";
import { v as verifyAuthentication, t as toPasskeyErrorResponse } from "../../../../../../../chunks/passkeys.js";
